mapper.select:

join t_merge_delivery b on tmergedeliverydetail.merge_delivery_id = b.id and b.del_flag = 0

    inner join sys_user u on u.user_name = tmergedeliverydetail.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tmergedeliverydetail.del_flag = '0'
     and tmergedeliverydetail.merge_delivery_id = #{mergeDeliveryId}
     and tmergedeliverydetail.material_id = #{materialId}
     and tmergedeliverydetail.next_flag = #{nextFlag}
     and tmergedeliverydetail.predict_count = #{predictCount}
     and tmergedeliverydetail.predict_receive_count = #{predictReceiveCount}
     and tmergedeliverydetail.receive_count = #{receiveCount}
     and tmergedeliverydetail.small_predict_count = #{smallPredictCount}
     and tmergedeliverydetail.small_receive_count = #{smallReceiveCount}


${params.dataScope}
